import { Component, computed, inject, signal } from '@angular/core';
import { SelectionService } from './selection.service';
import { ShipmentListComponent } from './shipment-list.component';
import { INITIAL_SHIPMENTS, syncWithCarrier } from './shipments';

@Component({
  selector: 'app-root',
  imports: [ShipmentListComponent],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  protected readonly selection = inject(SelectionService);
  readonly shipments = signal(INITIAL_SHIPMENTS);
  readonly count = computed(() => this.shipments().length);
  // Written after an await. zone.js used to run change detection after the timer; without it only a signal write
  // schedules a refresh.
  readonly syncStatus = signal('Not synced yet');
  private nextNumber = 104;

  async refresh(): Promise<void> {
    this.syncStatus.set('Syncing…');
    const time = await syncWithCarrier();
    this.syncStatus.set(`Synced at ${time}`);
  }

  addShipment(): void {
    // A new array: the signal compares references, so a push into the old one would change nothing it can see.
    this.shipments.update((list) => [
      ...list,
      { id: `S-${this.nextNumber++}`, route: 'Berlin → Hamburg', status: 'In transit' }
    ]);
  }

  selectNext(): void {
    this.selection.selectNext(this.shipments().map((shipment) => shipment.id));
  }
}

