import { ChangeDetectionStrategy, Component, inject, input } from '@angular/core';
import { SelectionService } from './selection.service';

@Component({
  selector: 'app-shipment-list',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <ul class="list">
      @for (shipment of shipments(); track shipment.id) {
        <li
          class="row"
          data-testid="shipment-row"
          [class.is-selected]="selection.selectedId() === shipment.id"
          [attr.aria-selected]="selection.selectedId() === shipment.id"
        >
          <span class="id">{{ shipment.id }}</span>
          <span class="route">{{ shipment.route }}</span>
          <span class="status">{{ shipment.status }}</span>
        </li>
      }
    </ul>
  `,
  styleUrls: ['./shipment-list.component.css']
})
export class ShipmentListComponent {
  readonly shipments = input.required<{ id: string; route: string; status: string }[]>();
  protected readonly selection = inject(SelectionService);
}

