import { Injectable, signal } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class SelectionService {
  // A signal tells every view that reads it, OnPush views included, that the selection moved.
  private readonly selected = signal('S-101');
  readonly selectedId = this.selected.asReadonly();

  selectNext(ids: string[]): void {
    const index = ids.indexOf(this.selected());
    this.selected.set(ids[(index + 1) % ids.length]);
  }
}

