export const INITIAL_SHIPMENTS = [
  { id: 'S-101', route: 'Lisbon → Porto', status: 'In transit' },
  { id: 'S-102', route: 'Madrid → Valencia', status: 'Delayed' },
  { id: 'S-103', route: 'Paris → Lyon', status: 'Delivered' }
];

// Stands in for the carrier API: answers after 300 ms with the time of the sync.
export function syncWithCarrier(): Promise<string> {
  return new Promise((resolve) => setTimeout(() => resolve(new Date().toLocaleTimeString()), 300));
}
